(183, 'RED QUEN', NULL, '978-602-385-062-4', 'PT Mizan Publika', 2018, 'sembilan', 'Art Original', '813 VIC  r', '813', 'English', 'Bandung', NULL, NULL, NULL, 'Kisah distopia fantasi mendebarkan tentang seorang gadis berdarah merah biasa yang ternyata menyimpan kekuatan luar biasa milik kaum bangsawan berdarah perak.', NULL, '<004592>'),
(184, 'memorabilian 8 februari', NULL, '978-602-03-1056-5', 'PT Gramedia Pustaka Utama', 2014, 'pertama', 'Art Original', '813 WIN m', '813', 'English', 'JAKARTA', NULL, NULL, '160 hlmn.;20 cm.', 'Kisah fiksi remaja tentang merelakan masa lalu, memori cinta yang tersisa, dan pertemuan tak terduga yang mengubah segalanya di bulan Februari.', NULL, '<004202>'),
(185, 'KETUA OSIS KOPLAK', NULL, '978-602-6716-12-5', 'PT Mizan Media Utama', 2017, 'pertama', 'Art Original', '813WIS k', '813', 'English', 'Bandung', NULL, NULL, NULL, 'Novel komedi remaja sekolahan yang sangat menghibur, mengisahkan kekocakan, keusilan, dan tingkah laku absurd dari seorang ketua OSIS beserta teman-temannya.', NULL, '<005018>'),
(186, 'The Time Machine', 'H.G. Wells', '9786020382807', 'Percetakan Gramedia', 2018, NULL, 'Text', '813 WEL t', '813', 'English', 'SURABAYA', NULL, NULL, '160 hlmn.;18 cm.', 'The Time Machine adalah sebuah novel fiksi ilmiah oleh H. G. Wells, diterbitkan pada tahun 1895 dan ditulis sebagai narasi bingkai. Wells umumnya dikreditkan dengan mempopulerkan konsep perjalanan waktu dengan menggunakan kendaraan yang memungkinkan operator untuk melakukan perjalanan sengaja dan selektif maju atau mundur dalam waktu.', 'CamScanner_05-12-2023_09.45(1)_1.jpg.jpg', '<001987>'),
(187, 'THE TIME', NULL, '978-602-038-2814', 'PT Gramedia Pustaka Utama', 2018, 'Cetakan Pertama', 'Art Original', '813 WEL t', '813', 'English', 'JAKARTA', NULL, NULL, '160 pgs 18 cm', 'Kisah misteri dan petualangan yang melintasi batas waktu, membawa pembacanya pada pertanyaan filosofis tentang masa lalu dan takdir masa depan.', NULL, NULL),
(188, 'KING CAGE', 'Victoria Aveyard', '978-602-385-286-4', NULL, 0, NULL, 'Art Original', '813 VIC k', '813', 'Indonesia', 'USA', NULL, NULL, '700 hlm; 20cm', 'Buku ketiga dari seri Red Queen karya Victoria Aveyard, di mana sang tokoh utama harus bertahan hidup di dalam kurungan musuh terbesarnya sambil merencanakan pemberontakan.', NULL, '<005985>'),
(189, 'R Raja, Ratu, dan Rahasia', 'Wulanfadi', '978-602-6940-26-1', 'Best Media', 2018, NULL, 'Text', '813 WUL r', '813', 'English', 'Jl. Tambra Raya No. 23', NULL, NULL, '388 hlm.; 20,5 cm.', 'Raja terkenal sebagai sosok yang humoris, tegas, dan bergengsi tinggi, itu semua karena dia adalah anak tunggal dari pasangan pemilik SMA elit di Jakarta, SMA Adhi Wijaya. Meskipun begitu, Raja tetap seperti cowok remaja kebanyakan yang maniak film horor, hobi bermain basket, dan naksir cewek. Baca cerita selengkapnya dalam novel ini.', 'CamScanner_01-13-2023_15.24_7.jpg.jpg', '<000813><001033>'),
(190, 'Derana', NULL, '978-602-1036-10-2', 'TransMedia pustaka', 2019, NULL, 'Text', '813 WIR d', '813', 'English', 'Tangerang', NULL, NULL, 'vii + 186 hlm.; 19 cm', 'Laki-laki humoris dan terencana ini kerap menghabiskan waktunya untuk menyeruput kopi dan menikmati malam ia bermimpi ingin mengunjungi semua negara di dunia lagi-lagi ia menganggap bahwa setiap tempat pasti memiliki kisah cerita dan cinta yang bisa disampaikan', 'IMG-20231204-WA0027.jpg.jpg', '<001974>'),
(191, 'If You Know What Happened in Meme Comic Indonesia', 'Widya Arifianti', '978-602-0900-20-9', 'Loveable', 2015, 'Cetakan ke-9', 'Text', '817 WID i', '817', 'English', 'SURABAYA', NULL, NULL, 'vi + 258 hlm.; 19 cm.', 'Buku ini berisi kumpulan cerita lucu Meme Comic Indonesia.', 'CamScanner_29-05-2023_06.34_11.jpg.jpg', '<001112>'),
(192, 'Cermin Ajaib', 'Wicha', '978-602-341-170-2', 'Penerbit Bestari', 2017, 'Cetakan Pertama', 'Text', '813 WIC c', '813', 'English', 'SURABAYA', 'Cerita Hebat Anak Berbakat', NULL, 'vi + 138 hlm.; 20,5 cm.', 'Buku ini berisi kumpulan cerita yang ditulis oleh 23 penulis cilik.', 'WhatsApp_Image_2023-05-31_at_10.54.13.jpeg.jpeg', '<001126>'),
(193, 'lukisan malam', NULL, '978 -979 -1101 -19 -6', 'prestasi pustakarya', 2007, 'Volume 1', 'Art Original', '813 PUR l', '813', 'Indonesia', 'JAKARTA', NULL, NULL, '19cm x 11cm;289 hlm', 'Novel misteri dan drama yang menyajikan kisah-kisah tersembunyi yang menegangkan, rahasia keluarga, dan teka-teki di balik tenangnya malam.', 'cover_lukisan-malam-20251031164332.jpeg', '<004787>'),
(194, 'Sangaji : Menengok Desa Bunga', 'Rahmat Ruhyana', '978-979-571-435-4', 'Ganeca', 2007, NULL, 'Text', '813 RAH s', '813', 'English', 'South Africa', NULL, NULL, 'iv + 122 hlm.; ilus.: 20,5 cm.', 'Buku ini menceritakan tentang seorang anak yang bernama Sangaji. Ia sebenarnya anak kota yang pandai. Akan tetapi, ia merindukan udara desa. Ia menginginkan keluarganya bisa tinggal bersama kakeknya. Pada akhirnya, di waktu liburan sekolah, keluarga Sangaji benar-benar bisa ke Bandung. Bahkan, Sangaji sengaja pindah sekolah ke sana. Baca cerita lengkapnya dalam buku ini.', 'cover_sangaji-menengok-desa-bunga-20251031164229.jpg', '<001127>'),
(195, 'bumi', 'Tere Liye', '978-602-033-295-6', 'gramedi pustaka utama', 2014, 'cetakan tiga puluh empat', 'Art Original', '813 TER b', '813', 'Indonesia', 'JAKARTA', NULL, NULL, '440 HLM ; 20 cm', 'Novel petualangan fantasi epik karya Tere Liye yang menjadi awal seri Dunia Paralel, menceritakan perjalanan menakjubkan Raib, Seli, dan Ali menjelajahi klan-klan misterius.', 'cover_bumi-20251031160251.jpg', '<002571>');
INSERT INTO `buku_slims` (`id`, `judul`, `pengarang`, `isbn_issn`, `penerbit`, `tahun_terbit`, `edisi`, `gmd`, `no_panggil`, `klasifikasi`, `bahasa`, `tempat_terbit`, `judul_seri`, `subjek_kategori`, `deskripsi_fisik`, `deskripsi_abstrak`, `nama_file_cover`, `barcode_item`) VALUES
(196, 'Bukan buku nikah', NULL, '978-623-6619-86-5', 'Loveble', 2021, NULL, 'Art Original', '813 RIA b', '800', 'English', 'Jakarta Selatan', NULL, NULL, NULL, 'Novel romansa komedi kontemporer tentang lika-liku pencarian cinta sejati, kencan yang gagal, dan kepelikan menuju jenjang pernikahan.', 'cover_bukan-buku-nikah-20251031163634.jpg', '<004784>'),
(197, 'through', 'Rania thahirah', '978-623-04-0213-5', 'Bhuana Sastra', 2021, 'Cetakan Pertama', 'Art Original', '813 RAN t', NULL, 'Indonesia', 'JAKARTA', NULL, NULL, '427 HLM ; 12,5 cm x 18,5 cm', 'Novel remaja karya Rania Thahirah yang mengisahkan perjuangan batin melewati trauma masa lalu, persahabatan, dan proses menemukan jati diri yang sebenarnya.', 'cover_through-20251031161900.jpg', '<004871>'),
(198, 'Monas i\'m in love', NULL, '602-8096-31-8', 'Examedia', 2008, 'pertama', 'Art Original', '813 RAN m', '800', 'English', 'Bandung', NULL, NULL, NULL, 'Kisah cinta remaja metropolitan metropolitan yang segar dan romantis, dengan latar belakang keriuhan dan romansa tersembunyi di sudut-sudut kota Jakarta.', 'cover_monas-i-m-in-love-20251031163055.jpg', NULL),
(199, 'Smart Melly', 'Putri Retno Pambayun', '978-979-066-079-3', 'PT Mizan Pustaka', 2011, 'Cetakan ke-IV', 'Text', '813 PUT s', '813', 'English', 'Palembang', 'Kecil-Kecil Punya Karya', NULL, '100 hlm.; ilus.: 21 cm', 'Buku ini menceritakan tentang seorang gadis bernama Melly Helmington yang merupakan putri satu-satunya dari keluarga Helmington, berumur sebelas tahun, dan duduk di kelas lima Hillque Elementary School. Melly berwajah cantik, berambut pirang lurus sepunggung, kulitnya putih, dan bermata biru. Melly pandai matematika, sains, dan juga balet. Melly tinggal bersama orangtuanya, namun karena sibuk, ia diurus oleh beberapa pelayan yang dipekerjakan oleh orangtua Melly. Seperti apa ya kegiatan Melly disekolah? Lalu, siapakah Alice dan apa yang terjadi saat Melly meninggalkan rumah neneknya?', 'cover_smart-melly-20251031162850.jpg', '<001545>'),
(200, 'psychic detective yamukumo', 'hitomiwa', NULL, 'manabu kaminaga', 2017, 'CETAKAN 3', 'Art Original', '813 `AKA p', '813', 'Indonesia', 'Tokyo', NULL, NULL, '360 hlm;  13cm x 20cm', 'Novel detektif supranatural asal Jepang (Yakumo) yang memecahkan kasus-kasus misterius kepolisian menggunakan kemampuan cenayang melihat roh orang mati.', 'cover_psychic-detective-yamukumo-20251031161921.jpg', '<004541>'),
(201, 'Treat You Better', 'Hana Nabilah', '978-602-04-6121-2', 'PT Elex Media Komputindo', 2018, 'CETAKAN 1', 'Text', '813 HAN t', '813', 'Indonesia', 'SURABAYA', NULL, NULL, 'viii + 276 hlm.: ilus.; 19,5 cm.', 'Andrea adalah ketua komdis yang disegani semua angkatan di bawahnya. Ekspresi serta tatapannya membuat para mahasiswa baru tidak ingin bersitatap dengannya.  Baca selengkapnya dalam novel ini.', 'cover_treat-you-better-20251030164322.jpg', '<000800>'),
(202, 'Smart Melly', NULL, '978-979-066-079-3', 'PT Mizan Media Utama', 2011, '4', 'Art Original', '813 PUT s', '800', 'English', 'Bandung', NULL, NULL, NULL, 'Buku cerita remaja inspiratif yang menyoroti kehidupan Melly yang cerdas, mandiri, dan usil dalam menghadapi dinamika pertemanan dan kehidupan sekolahnya.', NULL, NULL),
(203, 'Cinta Brontosaurus', 'Raditya Dika', '978-979-780-059-8', 'Gagasmedia', 2006, NULL, 'Text', '813 RAD c', '813', 'English', 'JAKARTA', NULL, NULL, 'viii + 152 hlm.; 11,5 x 19 cm.', 'Ada satu adegan yang mengharuskan gue berantem ama orang di depan orang banyak.. Gue akting dengan segenap jiwa dan raga. Dengan menyeimbangkan antara emosi dan karakter. Dengan masuk ke jiwa sang tokoh. Dengan total. Layaknya Tom Krus minum Irex, Uoh!  Baca kisah selengkapnya dalam novel ini.', 'cover_cinta-brontosaurus-20251031155520.jpg', NULL),
(204, 'Anatomic Habit', 'James Clear', '978-602-06-3317-6', 'P.T Gramedia', 2019, NULL, 'Text', '155.25 JAM a', '155.25 JAM a', 'Indonesia', 'Jagakarsa, Jakarta Selatan', NULL, '<Psikoterapi>', NULL, 'Buku ini memberikan panduan praktis dan teruji untuk membangun kebiasaan baik dan menghilangkan kebiasaan buruk setiap harinya, membantu pembaca mencapai potensi maksimal mereka.', NULL, NULL),
(205, 'Laut Bercerita', 'Leila S. C', '9786024248239', 'P.T Gramedia', 2017, NULL, 'Text', NULL, NULL, 'Indonesia', 'DKI Jakarta', NULL, '<Novel><Novel Dewasa>', NULL, 'Novel yang mengisahkan perjuangan para aktivis mahasiswa yang diculik pada masa Orde Baru, menyuarakan kebenaran, perlawanan, dan kepedihan mendalam dari keluarga yang ditinggalkan.', NULL, NULL),
(206, 'Cinta  di anatara kita yang tak pandai bicara', 'eru wilanda', '978-979-780-956-0', 'Gagasmedia', 2020, NULL, 'Text', NULL, NULL, 'Indonesia', 'DKI Jakarta', NULL, '<Novel><Fiksi Remaja>', '13 x 19 cm ,. 174 hlm', 'Kisah fiksi remaja tentang dinamika cinta dan komunikasi di antara dua remaja yang sulit mengungkapkan perasaan mereka secara jujur.', NULL, NULL),
(207, 'Hans', 'Risa Saraswati', '978- 602-220-216-5', 'PT Bukune Kreatif Cipta', 2017, 'Cet.3', 'Text', NULL, NULL, 'Indonesia', 'DKI Jakarta', NULL, '<Novel><Fiksi Remaja>', NULL, 'Kisah misteri tentang sosok hantu anak Belanda bernama Hans, menceritakan masa lalunya yang kelam dan interaksinya di dunia yang tak kasat mata.', NULL, NULL),
(208, 'Posessif Bro', 'Chintya S', '978-602-6940-89-6', 'MEDIA INDONESIA', 2017, 'pertama', 'Text', '813 CHI p', '813 CHI p', 'Indonesia', 'Depok,Jawa Barat', NULL, '<Novel>', '20,5 x  14 cm., 536 hlm', 'Novel yang menceritakan tentang hubungan romansa dengan seorang pria yang memiliki sifat posesif, membawa dinamika unik dan tantangan dalam kisah cinta mereka.', NULL, NULL),
(209, 'me vs celebrity', 'Despersa', '978-623-7524-02-1', 'Galaxy media', 2019, 'Cet.1', 'Text', NULL, NULL, 'Indonesia', 'Jakarta Pusat', NULL, '<Novel><Fiksi Remaja>', '13 x 19 cm., 300 hlm', 'Kisah fiksi remaja yang menarik tentang seorang gadis biasa yang tanpa sengaja berurusan dan terlibat konflik romantis dengan seorang selebriti terkenal.', NULL, NULL),
(210, 'Azzamine', 'Sophie Aulia', '978-602-220-433-6', 'bukune', 2022, NULL, 'Art Original', '813 SOP a', '813', 'Indonesia', 'Jl. Moh khafi', NULL, '<Sastra>', '368+viii; 13x19cm', '“Kalau saya sudah sayang sama kamu, angka-angka yang besar nggak akan bisa menggambarkan rasa sayang saya ke kamu, Jasmine.”\n\n“Terus digambarin pake apa?”\n\n“Sepertiga.”\n\n“Cuma sepertiga?”\n\n“Iya, saya akan selalu langitkan namamu di sepertiga malam saya, Jasmine.”\n\n\nRaden Azzam Al-Baihaqi datang secara tiba-tiba di hidup Haura Jasmine lewat sebuah perjodohan. Jasmine yang tidak siap dengan perjodohan ini pun meminta Azzam untuk mundur. Bukan karena tidak suka, melainkan Jasmine si pemalas ini merasa tidak pantas bersanding dengan Azzam yang selalu membawa keteduhan di tingkah laku dan tutur katanya.\n\nJasmine terus menghindar, tetapi Azzam dengan kelembutannya selalu membuat Jasmine meleleh. Semakin ia menjauh, Azzam justru semakin terngiang di dalam pikiran Jasmine. Di sisi lain, Jasmine masih bersama Deka, kekasih yang begitu menyayanginya selama empat tahun terakhir.\n\nJasmine pun harus segera menentukan pilihan hatinya. Azzam atau Deka. Apakah keputusannya akan mendatangkan bahagia atau luka yang bertahan lama?', 'cover_azzamine-20260511151302.jpg', NULL),
(211, 'Kisah dari halaman belakang', 'Wacaku', '978-623-00-4760-2', 'Pt alex media komputindo', 2023, NULL, 'Text', '813 wa k', '813 wa k', 'Indonesia', 'DKI Jakarta', NULL, '<Novel><Keluarga>', '19,5 x 12,5 cm,.354 halaman', 'Novel bertema keluarga yang menyajikan kisah-kisah hangat, rahasia masa lalu, dan keharuan yang terjadi di sekitar kehidupan sehari-hari.', 'cover_kisah-dari-halaman-belakang-20260722155638.jpg', NULL),
(212, 'The Course of Love', 'Alain De Botton', '978-602-291-827-1', 'bentang pustaka', 2021, 'Cet. 1', 'Text', '813 ALA t', '813', 'Indonesia', 'Sleman,Yogyakarta', NULL, '<Novel>', 'vi+270hlm.;20,5cm.', 'Novel yang mengeksplorasi perjalanan cinta secara realistis, dari debaran awal jatuh cinta hingga tantangan mempertahankan hubungan pernikahan jangka panjang.', 'cover_the-course-of-love-20260722155537.jpg', NULL),
(213, 'Orang - Orang Oetimu : Sebuah Novel', 'Felix K. Nesi', '978-979-1260-89-3', 'CV. Marjin Kiri', 2019, 'cet.1', 'Text', '813 FEL o', '813', 'Indonesia', 'Tangerang', NULL, '<Novel>', 'i-viii+220 hlm, 14x20,3 cm', 'Karya sastra luar biasa yang mengangkat kisah sejarah, benturan budaya, dan pergulatan masyarakat di Timur Indonesia dengan gaya penceritaan yang kuat.', 'cover_orang-orang-oetimu-sebuah-novel-20260722155445.jpg', NULL),
(214, 'dia yang ada di diantara kita', 'Ari keling', '978-602-483-104-2', NULL, 2018, NULL, 'Text', NULL, NULL, 'Indonesia', 'DKI Jakarta', NULL, '<Novel><Fiksi Remaja>', '19 x 13 cm ., 160 hlm', 'Kisah fiksi remaja yang penuh teka-teki mengenai sosok misterius yang hadir dan mengubah dinamika pertemanan di antara mereka.', 'cover_dia-yang-ada-di-diantara-kita-20260722155350.jpg', NULL),
(215, 'Sherlock Holmes : Pertualangan di Rumah Kosong', 'Sir Arthur Conan Doyle', '978-623-7465-84-3', 'Noktah', 2020, 'cet.1', 'Text', '813 SIR s', '813', 'Indonesia', 'Yogyakarta', NULL, '<Detektif>', '208hlm; 14x20cm', 'Kisah detektif legendaris Sherlock Holmes yang kembali secara dramatis untuk memecahkan misteri kejahatan membingungkan di sebuah rumah kosong.', 'cover_sherlock-holmes-pertualangan-di-rumah-kosong-20260722155321.jpg', NULL),
(216, 'Ibu Adalah Surgaku', 'Naomi Orlin', '978-602-6409-94-2', 'Penebit NUANSA', 2019, 'cet.1', 'Text', '813 NAO i', '813', 'Indonesia', 'DKI Jakarta', NULL, NULL, '14x21cm;200 hlm.', 'Buku yang menyentuh hati tentang pengorbanan tanpa batas, cinta kasih seorang ibu, dan bagaimana seorang anak memaknai kehadiran ibunya sebagai surga.', 'cover_ibu-adalah-surgaku-20260722155222.jpg', NULL),
(217, 'Rumah Tanpa Jendela', 'Asma Nadia', '978-602-0822-85-3', 'Republika Penerbit', 2017, 'cet.2', 'Text', '813 ASM r', '813', 'Indonesia', 'DKI Jakarta', NULL, '<Fiksi Remaja>', 'vi+215 hlm.; 13,5x20,5 cm', 'Kisah haru persahabatan antara Rara, anak pemulung yang memimpikan jendela di rumahnya, dengan Aldo, anak dari keluarga kaya yang merasa kesepian.', 'cover_rumah-tanpa-jendela-20260722155131.jpg', NULL),
(218, 'foodcourt corner', 'Yessica E. Daryanto', '978-602-02-5156-1', 'PT Elex Meda Komputindo', 2014, NULL, 'Text', NULL, NULL, 'Indonesia', 'DKI Jakarta', NULL, '<Novel><Fiksi Remaja>', '19,5 x 12,5 cm,. 254 hlm', 'Novel remaja yang menceritakan tentang pertemanan, cinta, dan pencarian jati diri yang berawal dari pertemuan tak terduga di sudut foodcourt.', 'cover_foodcourt-corner-20260722155048.jpg', NULL),
(219, 'Fanboy Attack', 'incainica', '978-602-428-7757', 'Kompas Gramedia', 2018, 'Cet.1', 'Text', '813 INC f', '813', 'Indonesia', 'DKI Jakarta', NULL, '<Novel>', NULL, 'Kisah seru dan lucu tentang lika-liku dunia para penggemar idola, menyajikan komedi romantis yang sangat akrab bagi para fangirl dan fanboy.', 'cover_fanboy-attack-20260722154925.jpg', NULL),
(220, 'Script', 'Wahyuni Kasno', '978-602-02-5537-8', 'PT. Elex Media Komputindo', 2014, NULL, 'Text', '813 WAH s', '813', 'Indonesia', 'DKI Jakarta', NULL, '<Novel><Fiksi Remaja>', '12,5x19,5 cm.,186 hlm.', 'Novel fiksi remaja yang membawa pembaca ke dalam intrik kehidupan sekolah, pertemanan, dan skenario hidup yang berjalan di luar rencana.', 'cover_script-20260722145640.jpg', NULL),
(221, 'Beyond Telepathy and practical mind reading', NULL, '978-602-5868-23-8', 'Bright Publisher', 2018, 'Cetakan 1', 'Art Original', '813 AND b', '813', 'Indonesia', 'Depok,Sleman, Yogyakarta', NULL, NULL, '172 hlm.; 13,5 cm x 20cm;', 'Buku yang mengupas fenomena kemampuan bawah sadar manusia dan memberikan wawasan praktis mengenai seni memahami pikiran orang lain.', 'cover_beyond-telepathy-and-practical-mind-reading-20260721092626.jpg', NULL),
(222, 'Hi Berlin 1998', NULL, '978-623-8668-11-', 'Clound Books', 2024, 'Cetakan 11', 'Art Original', '813 WAH h', '813', 'Indonesia', 'Depok,Jawa Barat', NULL, NULL, '349hlm.; 19,3 cm x13,5 cm.', 'Kisah fiksi berlatar belakang kota Berlin pada masa transisi tahun 1998, merangkai perjalanan emosional, harapan, dan konflik batin karakternya.', 'cover_hi-berlin-1998-20260721092510.jpg', NULL),
