INSERT INTO `facilities` (`id`, `title`, `description`, `icon`, `created_at`, `updated_at`) VALUES
(1, 'Laboratorium Komputer & AI Lab', 'Dilengkapi 40 unit PC spesifikasi tinggi dan koneksi fiber optik 1 Gbps.', '💻', '2026-09-28 06:48:42', '2026-09-28 06:48:42'),
(2, 'Perpustakaan Digital (E-Library)', 'Koleksi ribuan buku fisik dan akses gratis ke jurnal ilmiah serta ebook internasional.', '📚', '2026-09-28 06:48:42', '2026-09-28 06:48:42'),
(3, 'Laboratorium IPA Terpadu', 'Fasilitas praktikum Fisika, Kimia, dan Biologi lengkap bersertifikasi standar laboratorium.', '🔬', '2026-09-28 06:48:42', '2026-09-28 06:48:42'),
(4, 'Lap. Olahraga Multiguna & GOR Indoor', 'Lapangan basket, futsal, bulutangkis, dan sarana kebugaran siswa.', '🏀', '2026-09-28 06:48:42', '2026-09-28 06:48:42'),
(5, 'Aula Utama & Auditorium Cyber', 'Kapasitas 1.000 penonton dengan sistem sound & LED display modern.', '🏛️', '2026-09-28 06:48:42', '2026-09-28 06:48:42'),
(6, 'Kantin Sehat & Green Garden', 'Area kuliner higienis terverifikasi Dinkes dengan ruang terbuka hijau yang asri.', '🍃', '2026-09-28 06:48:42', '2026-09-28 06:48:42');
INSERT INTO `kelas_pelatihan` (`id`, `judul`, `deskripsi`, `tipe`, `biaya`, `link`, `created_at`, `updated_at`) VALUES
(1, 'Mastering React & Next.js untuk Front-End Modern', 'Pelajari cara membangun antarmuka web modern, interaktif, dan super cepat menggunakan React dan framework Next.js 14 lengkap dengan Server Components.', 'PPLG', 'Gratis', 'https://example.com/course/nextjs-mastery', '2026-09-29 06:31:08', '2026-09-29 06:31:08'),
(2, 'Dasar Pemrograman Python & Data Science', 'Kelas fundamental untuk pemula yang ingin terjun ke dunia Data Science, Machine Learning, dan otomatisasi dengan Python.', 'PPLG', 'Biaya tertera', 'https://example.com/course/python-basics', '2026-09-29 06:31:08', '2026-09-29 06:31:08'),
(3, 'Konfigurasi Jaringan Dasar dengan Cisco Packet Tracer', 'Simulasi jaringan lokal (LAN), routing, dan switching menggunakan software standar industri dari Cisco.', 'TJKT', 'Gratis', 'https://example.com/course/cisco-basics', '2026-09-29 06:31:08', '2026-09-29 06:31:08'),
(4, 'Keamanan Siber & Ethical Hacking Pemula', 'Mengenal kerentanan jaringan web dan teknik penetrasi dasar untuk mengamankan infrastruktur server sekolah atau perusahaan.', 'TJKT', 'Biaya tertera', 'https://example.com/course/ethical-hacking', '2026-09-29 06:31:08', '2026-09-29 06:31:08'),
(5, 'Desain Logo & Branding Menggunakan Adobe Illustrator', 'Kuasai pembuatan logo vektor profesional, perpaduan tipografi, dan penyusunan brand guideline dari nol.', 'DKV', 'Gratis', 'https://example.com/course/logo-branding', '2026-09-29 06:31:08', '2026-09-29 06:31:08'),
(6, 'UI/UX Design: Prototyping Interaktif di Figma', 'Fokus pada pengalaman pengguna (UX) dan antarmuka aplikasi (UI). Pelajari wireframing hingga high-fidelity prototype yang siap diserahkan ke developer.', 'DKV', 'Biaya tertera', 'https://example.com/course/figma-uiux', '2026-09-29 06:31:08', '2026-09-29 06:31:08'),
(7, 'Teknik Pengambilan Gambar Sinematik', 'Pelajari rahasia komposisi, lighting, dan pergerakan kamera (camera movement) untuk menghasilkan video standar film komersial.', 'BCF', 'Gratis', 'https://example.com/course/cinematic-camera', '2026-09-29 06:31:08', '2026-09-29 06:31:08'),
(8, 'Video Editing Transisi & Color Grading di DaVinci Resolve', 'Langkah demi langkah melakukan color correction dan grading profesional untuk memberikan nuansa hollywood pada video Anda.', 'BCF', 'Biaya tertera', 'https://example.com/course/davinci-color', '2026-09-29 06:31:08', '2026-09-29 06:31:08'),
(9, 'Persiapan Wawancara Kerja & CV ATS Friendly', 'Strategi merancang Curriculum Vitae yang lolos sistem ATS (Applicant Tracking System) dan taktik menjawab pertanyaan wawancara rekruter.', 'Karir', 'Gratis', 'https://example.com/course/ats-cv', '2026-09-29 06:31:08', '2026-09-29 06:31:08'),
(10, 'Public Speaking & Personal Branding di LinkedIn', 'Bangun kepercayaan diri di depan umum dan optimalkan profil LinkedIn Anda agar diincar oleh headhunter perusahaan top.', 'Karir', 'Gratis', 'https://example.com/course/linkedin-branding', '2026-09-29 06:31:08', '2026-09-29 06:31:08');
