INSERT INTO `news` (`id`, `title`, `category`, `date`, `summary`, `content`, `image`, `created_at`, `updated_at`, `author_id`, `slug`, `status`, `views_count`) VALUES
(1, 'Tim Robotik SMA 1 Meraih Medali Emas Olimpiade Sains Nasional 2026', 'Prestasi', '2026-08-05', 'Tim robotik siswa SMA Negeri 1 berhasil membawa pulang trofi juara pertama dalam kompetisi OSN bidang Teknologi.', 'Kabar membanggakan datang dari ajang Olimpiade Sains Nasional (OSN) 2026. Tim robotik SMA 1 berhasil mengalahkan puluhan sekolah pesaing dengan inovasi robot pemilah sampah otomatis berbasis AI.', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&q=80&w=800', '2026-09-28 06:48:42', '2026-09-28 06:48:42', NULL, NULL, 'published', 0),
(2, 'Pelaksanaan Penerimaan Peserta Didik Baru (PPDB) Tahun Ajaran 2026/2027', 'Pengumuman', '2026-08-01', 'Informasi lengkap mengenai jadwal, jalur pendaftaran, dan persyaratan berkas untuk calon siswa baru.', 'Pendaftaran PPDB SMA 1 Antigravity telah dibuka secara online. Terdapat 3 jalur pendaftaran yaitu Jalur Prestasi, Jalur Zonasi, dan Jalur Afirmasi.', 'https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&q=80&w=800', '2026-09-28 06:48:42', '2026-09-28 06:48:42', NULL, NULL, 'published', 0),
(3, 'Workshop Digital Literacy dan Etika Media Sosial bagi Siswa Kelas X', 'Kegiatan', '2026-07-28', 'Meningkatkan kesadaran digital dan literasi informasi di era AI bagi generasi muda.', 'Sekolah menyelenggarakan workshop literasi digital yang menghadirkan pakar cybersecurity dan komunikasi digital untuk membekali siswa dalam menyaring informasi hoax.', 'https://images.unsplash.com/photo-1531482615713-2afd69097998?auto=format&fit=crop&q=80&w=800', '2026-09-28 06:48:42', '2026-09-28 06:48:42', NULL, NULL, 'published', 0),
(4, 'Siswa PPLG Kembangkan Aplikasi Pemantau Kualitas Udara Berbasis IoT', 'Teknologi', '2026-09-01', 'Inovasi teknologi IoT karya siswa untuk memantau kualitas udara di lingkungan sekolah.', 'Siswa kelas XII dari program keahlian Pengembangan Perangkat Lunak dan Gim (PPLG) berhasil merancang purwarupa sistem pemantau udara berbasis Internet of Things (IoT). Alat ini terintegrasi dengan aplikasi mobile yang memberikan peringatan jika tingkat polusi udara melebihi batas wajar. Proyek ini mendapat apresiasi dari Dinas Lingkungan Hidup setempat.', 'https://images.unsplash.com/photo-1518770660439-4636190af475?q=80&w=1200&auto=format&fit=crop', '2026-09-29 06:04:00', '2026-09-29 06:04:00', 1, 'siswa-pplg-kembangkan-aplikasi-iot', 'published', 450),
(5, 'SMK Prestasi Prima Teken MoU dengan 5 Perusahaan Teknologi Terkemuka', 'Pengumuman', '2026-09-05', 'Kerjasama strategis untuk menjamin penyerapan lulusan ke dunia kerja.', 'Sebagai wujud komitmen link and match dengan dunia industri, SMK Prestasi Prima secara resmi menandatangani Nota Kesepahaman (MoU) dengan 5 raksasa teknologi nasional. Kerjasama ini mencakup penyelarasan kurikulum, program magang eksklusif, hingga rekrutmen langsung bagi lulusan terbaik. Kepala Sekolah menyatakan ini adalah lompatan besar untuk sekolah.', 'https://images.unsplash.com/photo-1556761175-5973dc0f32d7?q=80&w=1200&auto=format&fit=crop', '2026-09-29 06:04:00', '2026-09-29 06:04:00', 1, 'mou-dengan-5-perusahaan-teknologi', 'published', 1200),
(6, 'Tim Futsal Sekolah Berhasil Menembus Final Liga Pelajar Nasional', 'Olahraga', '2026-09-10', 'Kemenangan dramatis melalui adu penalti membawa tim sekolah ke puncak klasemen.', 'Pertandingan sengit melawan juara bertahan dari provinsi sebelah berakhir manis bagi tim futsal SMK Prestasi Prima. Melalui drama adu penalti yang mendebarkan, penjaga gawang kita berhasil menepis dua tendangan krusial. Mari dukung tim kebanggaan kita di laga final hari Minggu besok di GOR Utama!', 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?q=80&w=1200&auto=format&fit=crop', '2026-09-29 06:04:00', '2026-09-29 06:04:00', 1, 'tim-futsal-masuk-final', 'published', 3200),
(7, 'Karya Film Pendek Siswa BCF Terpilih Diputar di Festival Film Indie', 'Prestasi', '2026-09-12', 'Film dokumenter berjudul \"Jejak Langkah\" diakui kualitasnya oleh sineas profesional.', 'Film dokumenter pendek berdurasi 15 menit karya kelompok siswa jurusan Broadcast dan Perfilman (BCF) masuk dalam nominasi Karya Pelajar Terbaik di Festival Film Indie Nasional. Film yang mengangkat tema perjuangan anak pulau dalam menempuh pendidikan ini dinilai memiliki sinematografi yang setara dengan rumah produksi profesional.', 'https://images.unsplash.com/photo-1485846234645-a62644f84728?q=80&w=1200&auto=format&fit=crop', '2026-09-29 06:04:00', '2026-09-29 06:04:00', 1, 'karya-film-siswa-bcf-terpilih', 'published', 980),
(8, 'Workshop UI/UX Design Bersama Praktisi dari Startup Unicorn', 'Kegiatan', '2026-09-15', 'Siswa jurusan DKV dibekali ilmu desain aplikasi berstandar global.', 'Lebih dari 100 siswa antusias mengikuti workshop intensif bertema \"Designing for the Future\" yang diisi langsung oleh Senior Product Designer dari salah satu startup Unicorn ternama di Indonesia. Dalam sesi ini, siswa diajak melakukan bedah kasus desain antarmuka dan mencoba tools kolaborasi terkini seperti Figma dan FigJam.', 'https://images.unsplash.com/photo-1542744173-8e7e53415bb0?q=80&w=1200&auto=format&fit=crop', '2026-09-29 06:04:00', '2026-09-29 06:04:00', 1, 'workshop-ui-ux-design', 'published', 670),
(9, 'Pembaruan Fasilitas Lab Komputer TJKT dengan Server Generasi Terbaru', 'Akademik', '2026-09-18', 'Investasi sekolah untuk menunjang praktik jaringan dan komputasi awan (Cloud).', 'Merespon perkembangan industri Cloud Computing, pihak Yayasan telah resmi memperbarui infrastruktur Laboratorium Teknik Jaringan Komputer dan Telekomunikasi (TJKT). Lab kini dilengkapi dengan dua unit server enterprise baru serta perombakan topologi jaringan fiber optik internal guna menunjang praktik para siswa.', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?q=80&w=1200&auto=format&fit=crop', '2026-09-29 06:04:00', '2026-09-29 06:04:00', 1, 'pembaruan-fasilitas-lab-komputer-tjkt', 'published', 520),
(10, 'Jadwal Ujian Tengah Semester (UTS) Ganjil Tahun 2026', 'Pengumuman', '2026-09-20', 'Pelaksanaan UTS akan diselenggarakan secara full digital menggunakan sistem sekolah.', 'Diinformasikan kepada seluruh siswa dan wali murid bahwa Ujian Tengah Semester Ganjil akan dimulai pada tanggal 5 Oktober 2026. Berbeda dengan tahun sebelumnya, seluruh ujian akan dilaksanakan menggunakan CBT (Computer Based Test) melalui portal E-Learning sekolah untuk mengurangi penggunaan kertas.', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?q=80&w=1200&auto=format&fit=crop', '2026-09-29 06:04:00', '2026-09-29 06:04:00', 1, 'jadwal-uts-ganjil-2026', 'published', 2100),
(11, 'Siswa SMK Ciptakan Game Edukasi Sejarah Berbasis Virtual Reality', 'Teknologi', '2026-09-22', 'Belajar sejarah proklamasi kemerdekaan kini lebih nyata lewat teknologi VR.', 'Kolaborasi antar jurusan PPLG dan DKV kembali membuahkan hasil memukau. Mereka sukses menciptakan purwarupa gim edukasi sejarah menggunakan teknologi Virtual Reality (VR). Pengguna dapat merasakan sensasi berada langsung di rumah Soekarno pada saat perumusan naskah proklamasi.', 'https://images.unsplash.com/photo-1593508512255-86ab42a8e620?q=80&w=1200&auto=format&fit=crop', '2026-09-29 06:04:00', '2026-09-29 06:04:00', 1, 'game-edukasi-vr-karya-siswa', 'published', 1430),
(12, 'Pelepasan Kontingen Pramuka ke Jambore Nasional', 'Kegiatan', '2026-09-25', 'Tim Pramuka sekolah siap mengharumkan nama daerah di tingkat nasional.', 'Suasana haru dan bangga menyelimuti lapangan upacara saat Kepala Sekolah melepas 10 anggota Pramuka Penegak Bantara terpilih untuk mengikuti Jambore Nasional. Mereka telah menjalani pelatihan fisik dan mental selama 3 bulan penuh. Semoga kembali membawa piala dan pengalaman berharga!', 'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?q=80&w=1200&auto=format&fit=crop', '2026-09-29 06:04:00', '2026-09-29 06:04:48', 1, 'pelepasan-kontingen-pramuka', 'published', 891),
(13, 'Juara Umum Lomba Keterampilan Siswa (LKS) Tingkat Provinsi', 'Prestasi', '2026-09-28', 'Sekolah menyabet 4 medali emas di ajang bergengsi vokasi tahunan.', 'Luar biasa! SMK Prestasi Prima kembali mempertahankan gelar Juara Umum di Lomba Keterampilan Siswa (LKS) tingkat provinsi. Medali emas diraih dari bidang IT Software Solutions for Business, Web Technologies, Graphic Design Technology, dan Information Network Cabling. Selanjutnya mereka bersiap menuju LKS Nasional.', 'https://images.unsplash.com/photo-1596461404969-9ae70f2830c1?q=80&w=1200&auto=format&fit=crop', '2026-09-29 06:04:00', '2026-09-29 06:04:00', 1, 'juara-umum-lks-provinsi', 'published', 3800),
(14, 'SMK Prestasi Prima Raih Akreditasi A dengan Inovasi Kurikulum Digital Terpadu', 'Akademik', '2025-10-12', 'Pencapaian luar biasa ini merupakan hasil dedikasi seluruh civitas akademika dalam membangun ekosistem pendidikan masa depan yang berfokus pada kualitas.', 'Tahun ini, SMK Prestasi Prima secara resmi menerima sertifikat Akreditasi A dari Badan Akreditasi Nasional Sekolah/Madrasah (BAN-S/M). Penilaian ini difokuskan pada terobosan sekolah dalam menerapkan Kurikulum Merdeka yang dipadukan dengan infrastruktur digital modern. Kepala Sekolah menyampaikan apresiasi setinggi-tingginya kepada para guru, staf, dan siswa yang terus menjaga standar keunggulan.', 'https://images.unsplash.com/photo-1523240795612-9a054b0db644?q=80&w=1200&auto=format&fit=crop', '2026-09-29 06:06:07', '2026-09-29 06:06:07', 1, 'smk-prestasi-prima-raih-akreditasi-a', 'published', 1520),
(15, 'Pekan Kokurikuler IT: Siswa Sukses Kembangkan Aplikasi Smart School', 'Teknologi', '2025-10-15', 'Sebuah terobosan baru dalam digitalisasi lingkungan sekolah oleh siswa kelas XI.', 'Dalam rangka Pekan Kokurikuler IT, siswa-siswi jurusan Rekayasa Perangkat Lunak (RPL) mempresentasikan purwarupa (prototype) aplikasi \"Smart Presma\". Aplikasi ini dirancang untuk mempermudah presensi kehadiran menggunakan pemindai wajah (Face Recognition) serta notifikasi otomatis ke WhatsApp orang tua. Pengembangan memakan waktu 2 bulan dan didampingi langsung oleh guru ahli dari industri.', 'https://images.unsplash.com/photo-1531482615713-2afd69097998?q=80&w=800&auto=format&fit=crop', '2026-09-29 06:06:07', '2026-09-29 06:06:07', 1, 'siswa-kembangkan-aplikasi-smart-school', 'published', 840),
(16, 'Ultras Presma Menangkan Gelar Most Favorite Supporter DBL 2025', 'Olahraga', '2025-10-20', 'Kreativitas tanpa batas suporter basket SMK Prestasi Prima di kancah regional.', 'Kabar gembira datang dari lapangan basket! Meski tim utama harus puas di posisi runner-up, basis pendukung sekolah \"Ultras Presma\" berhasil dinobatkan sebagai Most Favorite Supporter di ajang DBL tingkat regional. Koreografi tiga dimensi bertema \"Future Tech\" yang mereka tampilkan di babak final berhasil memukau dewan juri dan seluruh penonton di arena.', 'https://images.unsplash.com/photo-1511886929837-354d827aae26?q=80&w=800&auto=format&fit=crop', '2026-09-29 06:06:07', '2026-09-29 06:06:07', 1, 'ultras-presma-most-favorite-supporter-dbl', 'published', 2105),
(17, 'Tim Robotik Maju ke Kompetisi Internasional di Singapura', 'Prestasi', '2025-10-25', 'Membawa nama harum bangsa melalui inovasi robot pemilah sampah otomatis.', 'Prestasi membanggakan kembali diukir oleh ekskul Robotik. Setelah menjuarai kompetisi tingkat nasional, tim robotik SMK Prestasi Prima secara resmi diundang untuk mewakili Indonesia dalam \"Asian Youth Robotics Innovation\" di Singapura. Robot \"Eco-Bot 2.0\" andalan mereka terbukti efektif memisahkan sampah organik dan anorganik dengan tingkat akurasi 98% berkat implementasi sensor cerdas.', 'https://images.unsplash.com/photo-1517694712202-14dd9538aa97?q=80&w=800&auto=format&fit=crop', '2026-09-29 06:06:07', '2026-09-29 06:06:07', 1, 'tim-robotik-maju-ke-singapura', 'published', 3450);
